// التحقق من وجود body (POST request فقط)
if (!$json.body) {
  console.log('⚠️ No body found - probably GET request');
  return [];
}

const body = $json.body;

// التحقق من صحة البيانات
if (!body?.entry?.[0]?.changes?.[0]?.value?.id) {
  console.log('❌ No valid comment data');
  return [];
}

// استخراج بيانات الكومنت
const commentId = body.entry[0].changes[0].value.id;
const commentText = body.entry[0].changes[0].value.text;
const fromUser = body.entry[0].changes[0].value.from;

// إدارة التكرار باستخدام Workflow Static Data
const store = $getWorkflowStaticData('global');
store.processedComments = store.processedComments || {};

const now = Date.now();
const ttl = 30 * 60 * 1000; // 30 دقيقة (زيادة الوقت للأمان)

// تنظيف السجلات القديمة (أكثر من 30 دقيقة)
Object.keys(store.processedComments).forEach(id => {
  if (now - store.processedComments[id] > ttl) {
    delete store.processedComments[id];
  }
});

// فحص إذا تم معالجة الكومنت من قبل
if (store.processedComments[commentId]) {
  const secondsAgo = Math.floor((now - store.processedComments[commentId]) / 1000);
  console.log(`🛑 DUPLICATE DETECTED! Comment ${commentId} was processed ${secondsAgo}s ago - STOPPING`);
  return [];
}

// تسجيل الكومنت كمعالج
store.processedComments[commentId] = now;
console.log(`✅ Processing NEW comment ${commentId}`);
console.log(`   Text: "${commentText}" | From: @${fromUser.username}`);

// إرجاع البيانات المنسقة
return [{
  json: {
    comment_id: commentId,
    text: commentText,
    from: fromUser,
    timestamp: body.entry[0].time,
    orig_body: body
  }
}];

